const catalogById = new Map<string, CatalogAsset>();
for (const a of ASSET_CATALOG) {
  catalogById.set(a.id.toLowerCase(), a);
  if (a.aliases) {
    for (const al of a.aliases) catalogById.set(al.toLowerCase(), a);
  }
}

export function getCatalogAssetById(id: string): CatalogAsset | undefined {
  if (!id) return undefined;
  return catalogById.get(id.toLowerCase().trim());
}
